// ========================================
// VOICE -> TEXT EXTRAKTION
// Extrahiert den transkribierten Text aus Whisper Response
// ========================================

const whisperResponse = $input.first().json;
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const firstName = $('Telegram Trigger').first().json.message.from.first_name || 'User';

return {
  json: {
    userMessage: whisperResponse.text || '',
    chatId: chatId,
    firstName: firstName,
    inputType: 'voice',
    messageId: $('Telegram Trigger').first().json.message.message_id
  }
};

// ========================================
// TEXT NACHRICHT EXTRAHIEREN
// Extrahiert den Text aus der Telegram-Nachricht
// ========================================

const msg = $('Telegram Trigger').first().json.message;

return {
  json: {
    userMessage: msg.text || '',
    chatId: msg.chat.id,
    firstName: msg.from.first_name || 'User',
    inputType: 'text',
    messageId: msg.message_id
  }
};

// ========================================
// INTENT ERKENNUNG
// Erkennt den Befehl/die Absicht des Nutzers
// ========================================

const input = $input.first().json;
const msg = input.userMessage.toLowerCase().trim();

// Intent-Mapping
let intent = 'conversation'; // Default: freie Konversation
let targetWorkflow = null;
let targetLabel = null;

// Einzelne Workflow-Abruf Patterns
const patterns = [
  { pattern: /\b(seo|geo|search|suche|organisch)\b/i, intent: 'fetch_single', workflow: 'seo_dashboard', label: 'SEO/GEO Dashboard' },
  { pattern: /\b(funnel|conversion|trichter|konversion)\b/i, intent: 'fetch_single', workflow: 'funnel_report', label: 'Funnel & Conversion' },
  { pattern: /\b(clarity|ux|usability|klick|heatmap|dead.?click|rage.?click)\b/i, intent: 'fetch_single', workflow: 'clarity_report', label: 'Microsoft Clarity' },
  { pattern: /\b(keyword|ranking|position|serp)\b/i, intent: 'fetch_single', workflow: 'keyword_tracker', label: 'Keyword Rankings' },
  { pattern: /\b(linkedin|nachricht|dm|message|inbox)\b/i, intent: 'fetch_single', workflow: 'linkedin_monitor', label: 'LinkedIn Monitor' },
  { pattern: /\b(ai.?visibility|sichtbarkeit|ki.?sichtbar|chatgpt|perplexity)\b/i, intent: 'fetch_single', workflow: 'ai_visibility', label: 'AI Visibility' },
  { pattern: /\b(comment|kommentar|sentiment|stimmung|meinung)\b/i, intent: 'fetch_single', workflow: 'comment_intelligence', label: 'Comment Intelligence' },

  // Komplett-Report
  { pattern: /\b(komplett|gesamt|alles|vollst.ndig|all|aktualisier.+alle|ganzer.?report)\b/i, intent: 'fetch_all', workflow: null, label: 'Kompletter Report' },

  // Letzten Report anzeigen
  { pattern: /\b(letzt|aktuel|zeig.+report|report.+zeig|zusammenfassung|summary|status|.berblick|.bersicht)\b/i, intent: 'show_latest', workflow: null, label: 'Letzter Report' },

  // Prioritaeten / Action Items
  { pattern: /\b(priorit|todo|aufgab|handlung|empfehlung|action|ma.nahm|was.+tun|next.?step)\b/i, intent: 'show_actions', workflow: null, label: 'Handlungsempfehlungen' },

  // Hilfe
  { pattern: /^\/(start|help|hilfe)$/i, intent: 'help', workflow: null, label: 'Hilfe' },
  { pattern: /\b(hilfe|was kannst|help|befehle|commands)\b/i, intent: 'help', workflow: null, label: 'Hilfe' }
];

for (const p of patterns) {
  if (p.pattern.test(msg)) {
    intent = p.intent;
    targetWorkflow = p.workflow;
    targetLabel = p.label;
    break;
  }
}

return {
  json: {
    ...input,
    intent: intent,
    targetWorkflow: targetWorkflow,
    targetLabel: targetLabel
  }
};

// ========================================
// EINZELNEN SUB-WORKFLOW ABRUFEN
// Baut die Webhook-URL dynamisch zusammen
// ========================================

const input = $('Intent erkennen').first().json;
const target = input.targetWorkflow;

// Webhook URL Mapping aus Umgebungsvariablen
const webhookMap = {
  seo_dashboard: $env.WEBHOOK_SEO_DASHBOARD,
  funnel_report: $env.WEBHOOK_FUNNEL_REPORT,
  clarity_report: $env.WEBHOOK_CLARITY_REPORT,
  keyword_tracker: $env.WEBHOOK_KEYWORD_TRACKER,
  linkedin_monitor: $env.WEBHOOK_LINKEDIN_MONITOR
};

// Google Sheet ID Mapping fuer direkte Sheet-Quellen
const sheetMap = {
  ai_visibility: $env.SHEET_AI_VISIBILITY,
  comment_intelligence: $env.SHEET_COMMENT_INTELLIGENCE
};

// Datumsbereich berechnen (aktuelle Woche)
const now = new Date();
const dayOfWeek = now.getDay();
const daysToLastMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - daysToLastMonday - 7);
const weekEnd = new Date(weekStart);
weekEnd.setDate(weekStart.getDate() + 6);
const formatDate = (d) => d.toISOString().split('T')[0];

const isWebhookSource = !!webhookMap[target];
const isSheetSource = !!sheetMap[target];

return {
  json: {
    ...input,
    webhookUrl: webhookMap[target] || null,
    sheetId: sheetMap[target] || null,
    isWebhookSource: isWebhookSource,
    isSheetSource: isSheetSource,
    dateRange: `${formatDate(weekStart)} bis ${formatDate(weekEnd)}`
  }
};

// ========================================
// EINZELERGEBNIS AUFBEREITEN + AI ANALYSE
// Formatiert das Ergebnis und laesst AI eine Zusammenfassung erstellen
// ========================================

const intentData = $('Intent erkennen').first().json;
let rawData;

try {
  rawData = $input.first().json;
} catch (e) {
  rawData = { error: 'Daten konnten nicht abgerufen werden: ' + e.message };
}

const hasError = !rawData || rawData.error || rawData.errorMessage;

return {
  json: {
    chatId: intentData.chatId,
    firstName: intentData.firstName,
    targetLabel: intentData.targetLabel,
    targetWorkflow: intentData.targetWorkflow,
    userMessage: intentData.userMessage,
    rawData: rawData,
    hasError: hasError,
    errorMessage: hasError ? (rawData?.error || rawData?.errorMessage || 'Unbekannter Fehler') : null
  }
};

// ========================================
// AI RESPONSE FUER TELEGRAM AUFBEREITEN
// Extrahiert den Text aus der nativen OpenAI Node Response
// (simplify: true -> $json.message.content)
// ========================================

const response = $input.first().json;
const intentData = $('Intent erkennen').first().json;

let responseText;
try {
  responseText = response.message.content;
} catch (e) {
  responseText = 'Die AI-Analyse konnte nicht durchgefuehrt werden. Bitte versuche es erneut.';
}

return {
  json: {
    chatId: intentData.chatId,
    responseText: responseText
  }
};

// ========================================
// LETZTEN REPORT / ACTION ITEMS AUFBEREITEN
// ========================================

const intentData = $('Intent erkennen').first().json;
const snapshot = $input.first().json;

let aiAnalysis = null;
let dateLabel = 'unbekannt';
let overallStatus = 'unknown';

try {
  if (snapshot.AIAnalysis) {
    aiAnalysis = JSON.parse(snapshot.AIAnalysis);
  }
  dateLabel = snapshot.DateLabel || 'unbekannt';
  overallStatus = snapshot.OverallStatus || 'unknown';
} catch (e) {
  // Fallback
}

return {
  json: {
    chatId: intentData.chatId,
    firstName: intentData.firstName,
    intent: intentData.intent,
    userMessage: intentData.userMessage,
    dateLabel: dateLabel,
    overallStatus: overallStatus,
    aiAnalysis: aiAnalysis,
    hasData: !!aiAnalysis
  }
};

